// n8n Code Node - Calculate wait minutes until 7 AM IST NEXT DAY after meeting

// ─── Pull data from "format data" node ───
const raw = $('format data').first().json;
const source = Array.isArray(raw) ? raw[0] : raw;
const firstName   = source.client.firstName;
const phoneNumber = source.client.phoneNumber;

const data = $input.first().json;
const meetingUTC = data.meeting.scheduledAtUTC;

// Parse meeting time
const meetingDate = new Date(meetingUTC);

// ─── Get meeting date in IST ───
const meetingDateIST = new Date(meetingDate.toLocaleString('en-US', { timeZone: 'Asia/Kolkata' }));
const istYear  = meetingDateIST.getFullYear();
const istMonth = meetingDateIST.getMonth();
const istDay   = meetingDateIST.getDate();

// ─── Next day 7 AM IST = Next day 01:30 AM UTC ───
const nextDay7AM_IST_inUTC = new Date(Date.UTC(istYear, istMonth, istDay + 1, 1, 30, 0));
// istDay + 1 → next day | 01:30 UTC = 07:00 IST

// ─── Current time ───
const now = new Date();

// ─── Calculate difference in minutes ───
const diffMs      = nextDay7AM_IST_inUTC.getTime() - now.getTime();
const diffMinutes = Math.round(diffMs / (1000 * 60));

// ─── Safety check ───
if (diffMinutes <= 0) {
  throw new Error(`⚠️ 7 AM IST next day has already passed! Diff: ${diffMinutes} mins`);
}

// ─── Format for readability ───
const hours   = Math.floor(diffMinutes / 60);
const minutes = diffMinutes % 60;

return [{
  json: {
    // ── Client info from "format data" ──
    firstName,
    phoneNumber,
    // ── Map this to your Wait node ──
    waitMinutes: diffMinutes,
    // ── For reference ──
    debug: {
      meetingDateIST:        meetingDateIST.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
      targetDateTime_IST:    nextDay7AM_IST_inUTC.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
      targetDateTime_UTC:    nextDay7AM_IST_inUTC.toISOString(),
      currentTime_IST:       now.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
      currentTime_UTC:       now.toISOString(),
      waitHours:             hours,
      waitMinutesRemainder:  minutes,
      humanReadable:         `Wait ${hours} hours and ${minutes} minutes`,
    }
  }
}];

// Code in JavaScript5 — extract attendee + pass meeting data forward
const webhookJson = $input.first().json;
const invitees = webhookJson.query.Invitees;
const longest = invitees.reduce((a, b) => a.length >= b.length ? a : b);

return [{
  json: {
    attendee: longest,
    _meetingQuery: webhookJson.query,       // ← carry meeting data forward
    _webhookUrl: webhookJson.webhookUrl,
    _executionMode: webhookJson.executionMode,
  }
}];

// n8n Code Node - Merge Kylas Meeting Webhook + Lead Data
const meetingData = $('kylas meeting webhook').first().json;
const leadData = $input.first().json;

// Helper
const get = (obj, path, fallback = "N/A") =>
  path.split('.').reduce((o, k) => (o && o[k] !== undefined ? o[k] : null), obj) ?? fallback;

// ─── MEETING WEBHOOK DATA (from "kylas meeting webhook" node) ───
const query = meetingData.query || {};

const meetingStatus     = query['Status']       || "N/A";
const meetingTitle      = query['Title']         || "N/A";
const meetingConductedBy = query['Conducted By'] || "N/A";
const meetingZoomId     = query['Zoom ID']       || "N/A";
const meetingInvitees   = Array.isArray(query['Invitees']) 
                            ? query['Invitees'].join(', ') 
                            : query['Invitees'] || "N/A";
const meetingFromRaw    = query['From']          || null;

// Parse meeting time & compute trigger time (+2 hours)
const meetingFromDate   = meetingFromRaw ? new Date(meetingFromRaw) : null;
const triggerAt2Hours   = meetingFromDate 
                            ? new Date(meetingFromDate.getTime() + 2 * 60 * 60 * 1000) 
                            : null;

const meetingFromIST    = meetingFromDate 
                            ? meetingFromDate.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }) 
                            : "N/A";
const triggerAtIST      = triggerAt2Hours 
                            ? triggerAt2Hours.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }) 
                            : "N/A";

const webhookUrl        = meetingData.webhookUrl  || "N/A";
const executionMode     = meetingData.executionMode || "N/A";

// ─── LEAD DATA (from current/previous node) ───
const cf      = leadData.customFieldValues || {};
const idStore = leadData.metaData?.idNameStore || {};

// Identity
const firstName   = get(leadData, 'firstName');
const lastName    = get(leadData, 'lastName');
const fullName    = `${firstName} ${lastName}`;

// Phone
const primaryPhone  = leadData.phoneNumbers?.find(p => p.primary) || leadData.phoneNumbers?.[0];
const phoneWithCode = primaryPhone ? `${primaryPhone.dialCode}${primaryPhone.value}` : "N/A";

// Email
const primaryEmail = leadData.emails?.find(e => e.primary) || leadData.emails?.[0];
const email        = primaryEmail?.value || "N/A";

// Lead Info
const leadType   = idStore.cfLeadType 
                     ? Object.values(idStore.cfLeadType).join(', ') 
                     : "N/A";
const source     = idStore.source 
                     ? Object.values(idStore.source).join(', ') 
                     : "N/A";
const subSources = idStore.cfSubSourceMultiPicklist 
                     ? Object.values(idStore.cfSubSourceMultiPicklist).join(', ') 
                     : "N/A";
const bestTimeToCall = idStore.cfWhatIsTheBestTimeToCallYou 
                         ? Object.values(idStore.cfWhatIsTheBestTimeToCallYou).join(', ') 
                         : "N/A";
const canAttendZoom  = idStore.cfConfirmIfYouCanAttendZoomVideoCallOnTime 
                         ? Object.values(idStore.cfConfirmIfYouCanAttendZoomVideoCallOnTime).join(', ') 
                         : "N/A";
const owner          = idStore.ownerId 
                         ? Object.values(idStore.ownerId).join(', ') 
                         : "N/A";

// UTM
const utm = {
  source:   get(leadData, 'utmSource'),
  medium:   get(leadData, 'utmMedium'),
  campaign: get(leadData, 'utmCampaign'),
  term:     get(leadData, 'utmTerm'),
  content:  get(leadData, 'utmContent'),
};

// Timestamps
const meetingScheduledOnRaw = leadData.meetingScheduledOn 
                                ? new Date(leadData.meetingScheduledOn) 
                                : null;
const meetingScheduledOnIST = meetingScheduledOnRaw 
                                ? meetingScheduledOnRaw.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }) 
                                : "N/A";

// ─── FINAL MERGED OUTPUT ───
return [{
  json: {

    // ── MEETING INFO (from webhook) ──
    meeting: {
      title:          meetingTitle,
      status:         meetingStatus,
      conductedBy:    meetingConductedBy,
      zoomId:         meetingZoomId,
      invitees:       meetingInvitees,
      scheduledAt:    meetingFromIST,
      scheduledAtUTC: meetingFromRaw,
      triggerAt:      triggerAtIST,           // 2 hours after meeting
      triggerAtUTC:   triggerAt2Hours?.toISOString() || "N/A",
      executionMode:  executionMode,
      webhookUrl:     webhookUrl,
    },

    // ── CLIENT INFO (from lead) ──
    client: {
      fullName,
      firstName,
      lastName,
      phoneNumber:    phoneWithCode,
      phoneRaw:       primaryPhone?.value || "N/A",
      countryCode:    primaryPhone?.dialCode || "N/A",
      email,
      city:           cf.cfCity || "N/A",
      leadId:         leadData.id,
      leadType,
      source,
      subSources,
      pipelineName:   get(leadData, 'pipeline.name'),
      pipelineStage:  get(leadData, 'pipeline.stage.name'),
      forecastingType: get(leadData, 'forecastingType'),
      score:          leadData.score ?? 0,
      owner,
    },

    // ── ZOOM & CALL DETAILS ──
    zoom: {
      meetingLink:    cf.cfZoomMeetingLink   || "N/A",
      meetingId:      cf.cfZoomMeetingId     || meetingZoomId,
      bestTimeToCall,
      canAttendZoom,
    },

    // ── LEAD CONTEXT ──
    leadContext: {
      profession:   cf.cfWhatIsYourCurrentProfessionBusiness         || "N/A",
      whyLearnDM:   cf.cfWhyDoYouWantToLearnDigitalMarketing         || "N/A",
      mainReason:   cf.cfTellUsTheMainReasonWhyYouWantToLearn        || "N/A",
    },

    // ── UTM TRACKING ──
    utm,

    // ── TIMESTAMPS ──
    timestamps: {
      meetingScheduledOn: meetingScheduledOnIST,
      createdAt:          leadData.createdAt,
      updatedAt:          leadData.updatedAt,
      convertedAt:        leadData.convertedAt,
    },

  }
}];

